-- SAIF v0.26A.1.21 exact house/property source evidence import
-- SAFETY: staging tables only; no runtime/ownership mutation.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
DELETE q FROM offline_property_source_queue q JOIN offline_property_source_sessions s ON s.id=q.session_id WHERE BINARY s.parser_version=BINARY 'saif-property-source-parser-v0.26A.1.21';
DELETE FROM offline_property_source_sessions WHERE BINARY parser_version=BINARY 'saif-property-source-parser-v0.26A.1.21';
SET @property_source_session_id := LAST_INSERT_ID();
UPDATE offline_property_source_sessions SET status='complete',completed_at=CURRENT_TIMESTAMP WHERE id=@property_source_session_id;
COMMIT;
SELECT 'PROPERTY_SOURCE_SESSION' AS section,id,status,total_rows,property_for_sale_rows,property_locked_rows,savegame_rows,enex_savehouse_rows,enex_property_rows,garage_rows,unique_property_slots,unique_save_positions,duplicate_extra_rows FROM offline_property_source_sessions WHERE id=@property_source_session_id;
SELECT 'QUEUE_SAFETY' AS section,COUNT(*) total_expected_255,SUM(enabled<>0) enabled_should_be_zero,SUM(apply_status<>'pending') nonpending_apply_should_be_zero,SUM(review_status<>'pending') nonpending_review_should_be_zero FROM offline_property_source_queue WHERE session_id=@property_source_session_id;
